INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(63198739, 'Primite Dragon Ether Beryl', '原石龙 异辉玄柱', '原石竜アナザー・ベリル', 'Effect Monster', 'Dragon', 'EARTH', 4, 1600, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡召唤的场合才能发动。从卡组把1张「原石」魔法·陷阱卡在自己场上盖放。 ②：把这张卡解放才能发动。从卡组把1只通常怪兽送去墓地。 ③：自己准备阶段，自己的场上或墓地有通常怪兽存在的场合才能发动。墓地的这张卡加入手卡。'),
(26462013, 'Primite Dragon Nether Berzelius', '原石龙 异狱玄矿', '原石竜ネザー・ベルセリウス', 'Fusion Monster', 'Dragon', 'EARTH', 8, 1600, NULL, '「原石」怪兽＋通常怪兽1只以上 ①：这张卡的攻击力上升作为这张卡的融合素材的通常怪兽数量×1000。 ②：只要这张卡在怪兽区域存在，等级·阶级·连接的数值是自己的场上·墓地的通常怪兽数量以下的对方场上的怪兽发动的效果无效化。 ③：这张卡从场上送去墓地的场合才能发动。从卡组把1只通常怪兽守备表示特殊召唤。'),
(29095457, 'Primite Drillbeam', '原石之穿光', '原石の穿光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把「原石的穿光」以外的手卡1张「原石」卡或1只通常怪兽给对方观看，以场上1张表侧表示卡为对象才能发动（除衍生物外的，通常怪兽或者5星以上的「原石」怪兽在自己场上存在的场合，也能不给人观看来发动）。作为对象的卡的效果无效并除外。 ②：自己场上有「原石」怪兽存在的场合，自己主要阶段才能发动。墓地的这张卡在自己场上盖放。'),
(99161253, 'Primite Fusion', '原石融合', '原石融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：包含通常怪兽的自己的场上·墓地·除外状态的怪兽作为融合素材回到卡组，把1只龙族融合怪兽融合召唤。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地把1只5星以上的「原石」怪兽加入手卡。'),
(41488249, 'Primite Howl', '原石之号咆', '原石の号咆', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：宣言1个通常怪兽的卡名才能发动。这个回合，自己的宣言的通常怪兽以及自己的「原石」怪兽的战斗发生的对自己的战斗伤害变成0。自己场上没有怪兽存在的场合，可以再把宣言的1只通常怪兽从自己的卡组·墓地特殊召唤。 ②：对方回合把墓地的这张卡除外，以自己的场上·墓地1只通常怪兽为对象才能发动。持有比那只怪兽高的攻击力的对方场上1只怪兽的控制权直到结束阶段得到。'),
(81418467, 'Primite Imperial Dragon', '原石龙 帝皇龙', '原石竜インペリアル・ドラゴン', 'Effect Monster', 'Dragon', 'EARTH', 6, 2600, NULL, '这张卡在把1只通常怪兽解放的场合才能召唤。这个卡名的①的效果1回合只能使用1次。 ①：对方主要阶段，把手卡的这张卡给对方观看才能发动。进行1只「原石」怪兽的召唤。 ②：这张卡上级召唤的场合才能发动。以下效果各适用。 ●对方场上的全部表侧表示怪兽的效果无效化。 ●种族或属性和自己墓地的通常怪兽的其中任意种相同的对方场上的怪兽全部除外。'),
(56506740, 'Primite Lordly Lode', '原石之皇脉', '原石の皇脈', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，从卡组把「原石的皇脉」以外的1张「原石」卡加入手卡。 ②：自己场上的通常怪兽以及「原石」怪兽的攻击力上升自己墓地的通常怪兽种类×300。 ③：宣言1个通常怪兽的卡名才能发动。宣言的1只通常怪兽从自己的手卡·卡组·墓地守备表示特殊召唤。这个回合，自己不能把特殊召唤的场上的怪兽的效果发动。'),
(92501449, 'Primite Roar', '原石之鸣狞', '原石の鳴獰', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：支付2000基本分，宣言1个通常怪兽的卡名才能发动。直到对方回合结束时，自己的宣言的通常怪兽以及自己的「原石」怪兽不会被战斗破坏。自己场上没有怪兽存在的场合，可以再把宣言的1只通常怪兽从卡组守备表示特殊召唤。 ②：对方把怪兽召唤的场合，把墓地的这张卡除外，以自己的场上·墓地1只通常怪兽为对象才能发动。持有比那只怪兽低的攻击力的场上1只怪兽除外。'),
(27556460, 'Primite Scream', '原石的反叫', '原石の反叫', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：除衍生物外的，通常怪兽或者5星以上的「原石」怪兽在自己场上存在，对方把怪兽召唤·特殊召唤之际才能发动。那个无效，那些怪兽除外。 ②：自己准备阶段，自己场上有「原石」怪兽存在的场合才能发动。墓地的这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(98154550, 'Primitive Butterfly', '原生蝴蝶', 'プリミティブ・バタフライ', 'Effect Monster', 'Insect', 'WIND', 5, 1200, 900, '①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，自己主要阶段才能发动。自己场上的全部昆虫族怪兽的等级上升1星。'),
(56063182, 'Primitive Planet Reichphobia', '肆世坏・赖祸比亚', '肆世壊＝ライフォビア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「恐吓爪牙族」怪兽或者「维萨斯-斯塔弗罗斯特」加入手卡。 ②：对方场上的怪兽的攻击力·守备力下降场上的守备表示怪兽数量×100。 ③：场上有守备表示怪兽3只以上存在的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(78933589, 'Primordial Soup', '原初之液', '原初のスープ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，自己的主要阶段时才能发动。让手卡最多2只名字带有「进化龙」的怪兽回到卡组洗切，并从卡组抽出回去数量的卡。「原初之液」在自己场上只能有1张表侧表示存在。'),
(8129306, 'Primula the Rikka Fairy', '六花精报春花', '六花精プリム', 'Effect Monster', 'Plant', 'WATER', 4, 800, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽被解放的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：以自己场上最多2只植物族怪兽为对象才能发动。那些怪兽的等级直到回合结束时上升2星。'),
(75574498, 'Princess Cologne', '珂珑公主', 'プリンセス・コロン', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 500, 2200, '4星怪兽×2 ①：这张卡超量召唤成功时，以自己墓地1只「玩具盒」为对象才能发动。那只怪兽特殊召唤。 ②：只要自己场上有其他怪兽存在，对方不能选择这张卡作为攻击对象，也不能作为效果的对象。 ③：自己场上的表侧表示的通常怪兽被战斗·效果破坏送去墓地的场合，把这张卡1个超量素材取除才能发动。从自己的卡组·墓地选1只通常怪兽守备表示特殊召唤。'),
(2316186, 'Princess Curran', '魔法之国的王女-库兰', '魔法の国の王女－クラン', 'Effect Monster', 'Spellcaster', 'DARK', 4, 2000, NULL, '这张卡不能通常召唤。这张卡只能通过「王女的试炼」的效果才能特殊召唤。自己准备阶段时，给与对方基本分对方场上存在的怪兽数量×600分数值的伤害。'),
(51371017, 'Princess of Tsurugi', '剑之女王', '剣の女王', 'Flip Effect Monster', 'Warrior', 'WIND', 3, 900, 700, '反转：对方场上每存在1张魔法·陷阱，对方受到500分的伤害。'),
(75917088, 'Princess Pikeru', '魔法之国的王女-绒儿', '魔法の国の王女－ピケル', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 2000, NULL, '这张卡不能通常召唤。这张卡只能通过「王女的试炼」的效果才能特殊召唤。自己准备阶段时，回复自己场上存在的怪兽数量×800的数值的基本分。'),
(11496832, 'Principug', '首席哈巴', 'プリンシパグ', 'Effect Monster', 'Beast', 'EARTH', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以原本卡名包含「守护者」的自己场上1只不能通常召唤的怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。 ②：可以把墓地的这张卡除外，以自己墓地1只不能通常召唤的「守护者」怪兽为对象，从以下效果选择1个发动。 ●作为对象的怪兽加入手卡。 ●把1张在作为对象的怪兽有卡名记述的卡从自己墓地加入手卡。'),
(78527720, 'Prinzessin', '灰姑娘', 'シンデレラ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 300, 600, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡·卡组把1只「南瓜马车」特殊召唤。场地区域有「急流山的金宫」存在的场合，可以再从卡组把1张「水晶鞋」给这张卡装备。 ②：这张卡直接攻击给与对方战斗伤害时，以这张卡装备的1张「水晶鞋」和场上1只表侧表示怪兽为对象才能发动。那张「水晶鞋」给那只怪兽装备。'),
(50088247, 'Prior of the Ice Barrier', '冰结界的传道师', '氷結界の伝道師', 'Effect Monster', 'Aqua', 'WATER', 2, 1000, 400, '①：自己场上有「冰结界」怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的回合，自己不能把5星以上的怪兽特殊召唤。 ②：把这张卡解放，以「冰结界的传道师」以外的自己墓地1只「冰结界」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(80234301, 'Prisman', '棱镜人', 'プリズマン', 'Normal Monster', 'Rock', 'LIGHT', 3, 800, 1000, '晶莹剔透的水晶凝固体。收集光线而射出激光。'),
(12612470, 'Procession of the Tea Jar', '童妖 茶壶', '童妖 茶壺', 'Tuner Monster', 'Zombie', 'DARK', 3, 500, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，和这张卡相同纵列的，里侧守备表示怪兽不能把表示形式变更，魔法与陷阱区域盖放的卡不能发动。 ②：自己主要阶段才能发动。这张卡向相邻的主要怪兽区域移动。 ③：怪兽区域的这张卡向其他的怪兽区域移动的场合发动。和这张卡相同纵列的其他怪兽全部变成里侧守备表示。'),
(300302070, 'Professor of Alchemy', NULL, NULL, 'Skill Card', 'Amnael', NULL, NULL, NULL, NULL, NULL),
(52615248, 'Progleo', '逐行狮', 'プログレオ', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1000, NULL, '衍生物以外的怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡是已连接召唤的场合，把这张卡所连接区1只自己怪兽和这张卡除外，以自己或者对方的墓地1只连接怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(39732186, 'Prohibit Snake', '禁止档案蛇', 'プロフィビット・スネーク', 'Effect Monster', 'Cyberse', 'LIGHT', 2, 500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的电子界族连接怪兽和对方怪兽进行战斗的伤害步骤开始时，把这张卡从手卡送去墓地才能发动。那只对方怪兽回到持有者手卡。 ②：这张卡在墓地存在，自己的电子界族怪兽战斗破坏对方怪兽送去墓地时，从自己墓地把1张卡除外，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽加入手卡。'),
(43711255, 'Prohibition', '禁止令', '禁止令', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '宣言1个卡名才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，宣言的卡名为原本卡名的双方的卡受以下所适用（对从这个效果的适用前开始在场上存在的卡不适用）。 ●不能在场上出现。 ●不能作卡的发动以及效果的发动和适用。 ●不能通常召唤·反转召唤·特殊召唤。 ●不能作攻击以及表示形式的变更。 ●不能作为要为需要素材的特殊召唤而用的素材。'),
(33280639, 'Prologue of the Destruction Swordsman', '破坏剑士的摇篮', '破壊剣士の揺籃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「破坏剑士的摇篮」在1回合只能发动1张。 ①：从卡组把「破坏剑士的摇篮」以外的1张「破坏剑」卡和1只「破坏之剑士」怪兽送去墓地才能发动。从自己的额外卡组·墓地选1只「破戒蛮龙-破坏龙」特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段破坏。 ②：把墓地的这张卡除外才能发动。这个回合，自己场上的「破坏剑」卡不会被战斗·效果破坏。'),
(75713017, 'Prometeor, the Burning Star', '燎星之天火流星神', '燎星のプロメテオロン', 'Effect Monster', 'Machine', 'FIRE', 8, 2800, 1000, '①：这张卡的攻击破坏主要怪兽区域的对方怪兽时，丢弃1张手卡才能发动。这张卡可以继续攻击。直到下个回合的结束时，那只怪兽存在过的区域不能使用。'),
(2772337, 'Promethean Princess, Bestower of Flames', '赐炎之咎姬', '賜炎の咎姫', 'Link Monster', 'Fiend', 'FIRE', NULL, 2700, NULL, '效果怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，自己不是炎属性怪兽不能特殊召唤。 ②：自己主要阶段才能发动。从自己墓地把1只炎属性怪兽特殊召唤。 ③：这张卡在墓地存在的状态，对方场上有怪兽特殊召唤的场合，以自己场上1只炎属性怪兽和对方场上1只怪兽为对象才能发动。那些怪兽破坏，这张卡特殊召唤。'),
(82213171, 'Prometheus, King of the Shadows', '暗王 普罗米修斯', '闇王プロメティス', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 800, '①：这张卡召唤成功的场合发动。选自己墓地的暗属性怪兽任意数量除外。这张卡的攻击力直到回合结束时上升除外数量×400。'),
(21414674, 'Prominence Hand', '日珥手', 'プロミネンス・ハンド', 'Effect Monster', 'Pyro', 'FIRE', 4, 600, 2000, '①：自己场上有「魔术手」「火焰手」「寒冰手」的其中任意种存在的场合，这张卡可以从手卡特殊召唤。'),
(89770167, 'Prominence, Molten Swordsman', '炎热刀 日珥', '炎熱刀プロミネンス', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 600, '1回合1次，把自己墓地存在的1只名字带有「熔岩」的怪兽从游戏中除外才能发动。这张卡的攻击力直到结束阶段时上升300。这个效果在对方回合也能发动。'),
(88617904, 'Promotion', '升变', 'プロモーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只3星以下的战士族·地属性怪兽为对象才能发动。那只怪兽送去墓地，从卡组把1只4星以上的战士族·地属性怪兽特殊召唤。那之后，原本的种族·属性是战士族·地属性的「人偶」怪兽在自己场上存在的场合，这个效果特殊召唤的怪兽的攻击力·守备力上升对方墓地的卡数量×100。'),
(50548657, 'Prompthorn', '提示符叉角羚', 'プロンプトホーン', 'Effect Monster', 'Cyberse', 'DARK', 1, 200, 400, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只4星以下的电子界族怪兽解放才能发动。等级合计直到变成和解放的怪兽的等级相同为止，从自己的卡组·墓地选电子界族通常怪兽任意数量特殊召唤。这个效果特殊召唤的怪兽在结束阶段除外。'),
(11373345, 'Proof of Powerlessness', '无力的证明', '無力の証明', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有7星以上的怪兽表侧表示存在的场合才能发动。对方场上表侧表示存在的5星以下的怪兽全部破坏。这张卡发动的回合，自己场上存在的怪兽不能攻击。'),
(85847157, 'Proof of Pruflas', '证明之普鲁弗拉斯', 'プルーフ・プルフラス', 'Effect Monster', 'Fiend', 'DARK', 3, 100, 100, '这个卡名的①的效果1回合只能使用1次。 ①：特殊召唤的怪兽不在自己场上存在的场合才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。把1只怪兽上级召唤。'),
(61681816, 'Propa Gandake', '宣传雁茸天狗', 'プロパ・ガンダケ', 'Effect Monster', 'Psychic', 'EARTH', 3, 500, 2000, '①：1回合1次，宣言自己场上的怪兽1个原本种族（兽族·昆虫族·植物族·岩石族）才能发动。这张卡变成宣言的种族。 ②：只要这张卡的①的效果适用的这张卡在怪兽区域存在，以下效果适用。 ●场上的表侧表示怪兽变成和这张卡相同种族。 ●和这张卡相同种族的场上的怪兽不会成为相同种族的对方场上的怪兽的效果的对象。'),
(56174248, 'Prophecy Destroyer', '魔导鬼士 迪亚勒', '魔導鬼士 ディアール', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2500, 1200, '这张卡在墓地存在的场合，把自己墓地3张名字带有「魔导书」的魔法卡从游戏中除外才能发动。这张卡从墓地特殊召唤。'),
(58036229, 'Protectcode Talker', '防卫码语者', 'プロテクトコード・トーカー', 'Link Monster', 'Cyberse', 'DARK', NULL, 2300, NULL, '效果怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己场上的连接4以上的连接怪兽不会成为对方的效果的对象，不会被战斗破坏。 ②：自己场上有「防火」连接怪兽存在的场合，连接标记合计直到3为止从自己墓地把连接怪兽任意数量除外才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果在对方回合也能发动。'),
(84339249, 'Protecting Spirit Loagaeth', '守护天灵 罗加埃斯', '守護天霊ロガエス', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2400, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的天使族怪兽的效果发动的场合才能发动。这张卡从手卡特殊召唤。 ②：以对方场上1张表侧表示卡和自己场上1只攻击表示怪兽为对象才能发动。那张对方的卡除外，那只自己怪兽变成守备表示。 ③：场上的这张卡被战斗·效果破坏的场合，以场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被战斗破坏。'),
(66367984, 'Protection of the Elements', '元素的加护', 'エレメントの加護', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：魔法·陷阱卡发动时，把自己场上1只表侧表示的「元素英雄」怪兽直到结束阶段除外才能发动。那个发动无效并破坏。 ②：自己场上有「元素英雄 地球侠」存在的场合，把墓地的这张卡除外才能发动。从自己的手卡·墓地的怪兽以及除外的自己怪兽之中选1只「元素英雄」怪兽无视召唤条件特殊召唤。'),
(11678191, 'Protective Soul Ailin', '守护灵 爱琳', '守護霊アイリン', 'Union Effect Monster', 'Fairy', 'LIGHT', 1, NULL, NULL, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「不屈斗士 磊磊」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽的表示形式1回合可以改变1次。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(90290572, 'Protector of The Agents - Moon', '代行者的近卫 穆恩', '代行者の近衛 ムーン', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1800, NULL, '天使族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「天空的圣域」或者有那个卡名记述的卡送去墓地。场上或者墓地有「天空的圣域」存在的场合，可以作为代替从自己的卡组·墓地选1只「神秘之代行者 厄斯」加入手卡。 ②：把自己场上1只天使族怪兽解放，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(24221739, 'Protector of the Sanctuary', '神殿守卫者', '神殿を守る者', 'Effect Monster', 'Fiend', 'EARTH', 4, 1100, 1900, '当这张卡在场上以表侧表示存在时，对方不能在抽卡阶段以外进行抽卡。'),
(10071456, 'Protector of the Throne', '王座保卫者', '王座の守護者', 'Normal Monster', 'Warrior', 'EARTH', 4, 800, 1500, '国王离开时，保卫王座不受外敌攻击的王妃。守备力高。'),
(47158777, 'Protector Whelp of the Destruction Swordsman', '破坏剑士的守护绊龙', '破壊剣士の守護絆竜', 'Link Monster', 'Dragon', 'LIGHT', NULL, 400, NULL, '怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「破坏剑」卡送去墓地。那之后，可以从手卡把1只「破坏之剑士」怪兽特殊召唤。 ②：对方场上没有怪兽存在的自己战斗阶段结束时，以这个回合没有攻击宣言的自己场上1只「破坏之剑士」怪兽为对象才能发动。给与对方那只怪兽的攻击力数值的伤害。'),
(72855441, 'Protector with Eyes of Blue', '青之眼护人', '青き眼の護人', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, 800, 1300, '「青色眼睛的护人」的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从手卡把1只光属性·1星调整特殊召唤。 ②：以自己场上1只效果怪兽为对象才能发动。那只怪兽送去墓地，从手卡把1只「青眼」怪兽特殊召唤。'),
(56187077, 'Proto Enneacraft - "orgIA"', '纠罪巧α’－愤怒“orgIA”', '糾罪巧α’－「orgIA」', 'Pendulum Flip Effect Monster', 'Machine', 'EARTH', 1, 100, 1000, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：手卡的怪兽的效果由对方发动时，把里侧表示的这张卡变成表侧守备表示才能发动。从卡组把1张「纠罪巧」卡加入手卡。 ③：这张卡反转的场合发动。对方场上1只怪兽破坏。'),
(26439287, 'Proto-Cyber Dragon', '原始电子龙', 'プロト・サイバー・ドラゴン', 'Effect Monster', 'Machine', 'LIGHT', 3, 1100, 600, '只要这张卡在场上表侧表示存在，卡名当作「电子龙」使用。'),
(5329790, 'Protocol Gardna', '协议守卫者', 'プロトコル・ガードナー', 'Link Monster', 'Cyberse', 'DARK', NULL, 1000, NULL, '电子界族怪兽2只 ①：对方不能选择这张卡所连接区的怪兽作为攻击对象。 ②：这张卡1回合只有1次不会被战斗破坏。那个时候，自己受到的战斗伤害变成0。'),
(49511705, 'Proton Blast', '铳炮击', '銃砲撃', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，进行投掷硬币的效果发动的场合，那个效果让表出现次数的以下效果适用。 ●1次以上：给与对方500伤害。 ●2次以上：选对方场上1张卡破坏。 ●3次以上：把对方手卡确认，从那之中选1张卡丢弃。 ②：进行投掷硬币2次以上的效果发动时，把墓地的这张卡除外才能发动。那些投掷硬币的结果全部当作表出现的状态使用。'),
(95091919, 'Prototype Psychic Blaster', '原型念力枪手', 'プロトタイプサイコガンナー', 'Effect Monster', 'Psychic', 'EARTH', 6, 2000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。自己的手卡·除外状态的1只4星以下的念动力族怪兽特殊召唤。 ②：这张卡在墓地存在的场合，支付1000基本分，从自己墓地把1只其他的念动力族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(25072579, 'Prototype Sky Striker Ace - Amatsu', '试作闪刀姬－天津', '試号閃刀姫－アマツ', 'Link Monster', 'Machine', 'DARK', NULL, 1500, NULL, '「闪刀姬」怪兽1只 自己对「试号闪刀姬-天津」1回合只能有1次特殊召唤，那些①②的效果1回合各能使用1次。 ①：对方场上的攻击力2000以上的怪兽把效果发动时才能发动。那个效果变成「对方场上1只「闪刀姬」连接怪兽破坏」。 ②：这张卡和对方怪兽进行战斗的攻击宣言时，以自己场上1只「闪刀姬」怪兽和对方场上1张卡为对象才能发动。那些卡破坏。'),
(24154052, 'Protron', '原型创机', 'プロトロン', 'Normal Monster', 'Cyberse', 'EARTH', 1, 100, 100, '电子空间找到的原种。它的信息量是未知数。'),
(22862454, 'Proxy Dragon', '代理龙', 'プロキシー・ドラゴン', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1400, NULL, '怪兽2只 ①：自己场上的卡被战斗·效果破坏的场合，可以作为代替把这张卡所连接区1只自己怪兽破坏。'),
(12450071, 'Proxy F Magician', '代理・F・魔术师', 'プロキシー・F・マジシャン', 'Link Monster', 'Cyberse', 'FIRE', NULL, 1400, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己场上的怪兽作为融合素材，把1只融合怪兽融合召唤。 ②：这张卡所连接区有融合怪兽融合召唤的场合才能发动。从手卡把1只攻击力1000以下的怪兽特殊召唤。'),
(16684346, 'Proxy Horse', '代理马', 'プロキシー・ホース', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1100, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上的这张卡作为电子界族怪兽的连接素材的场合，手卡的电子界族怪兽也能有最多1只作为连接素材。 ②：自己结束阶段把墓地的这张卡除外，以包含电子界族连接怪兽的自己墓地2只连接怪兽为对象才能发动。那些怪兽回到额外卡组。'),
(9798352, 'Prufinesse, the Tactical Trapper', '奇采之普鲁菲尼斯', '奇采のプルフィネス', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，从卡组把1张陷阱卡除外才能发动。这张卡的等级上升1星。 ②：以自己或者对方的墓地1张陷阱卡为对象才能发动。那张卡除外，这张卡的等级上升1星。 ③：这张卡被对方破坏的场合才能发动。选除外的1张自己的通常陷阱卡在自己场上盖放。'),
(77584012, 'Pseudo Space', '拟似空间', '擬似空間', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，从自己墓地把1张场地魔法卡除外才能发动。直到结束阶段，这张卡当作和除外的卡同名卡使用，得到相同效果。'),
(46291010, 'Psi-Beast', '念动力兽', 'サイキック・ビースト', 'Effect Monster', 'Psychic', 'EARTH', 2, 700, 500, '①：这张卡召唤成功时才能发动。从卡组把1只念动力族怪兽除外。这张卡的等级变成和这个效果除外的怪兽的等级相同。'),
(29417188, 'Psi-Blocker', '念动力阻挡者', 'サイキック・ブロッカー', 'Effect Monster', 'Psychic', 'WIND', 4, 1200, 300, '①：1回合1次，宣言1个卡名才能发动。直到对方回合结束时，宣言的卡名为原本卡名的双方的卡受以下所适用。 ●不能在场上出现。 ●不能作卡的发动以及效果的发动和适用。 ●不能通常召唤·反转召唤·特殊召唤。 ●不能作攻击以及表示形式的变更。 ●不能作为要为需要素材的特殊召唤而用的素材。'),
(16678947, 'Psi-Curse', '念动力诅咒', 'カース・サイキック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的念动力族怪兽被对方怪兽的攻击破坏送去墓地时才能发动。那个时候进行攻击的1只对方怪兽破坏，给与对方基本分破坏的自己的念动力族怪兽等级×300的数值的伤害。'),
(31328739, 'Psi-Impulse', '念动力脉冲', 'サイキック・インパルス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只念动力族怪兽解放发动。对方手卡全部加入卡组洗切。那之后，对方从卡组抽3张卡。'),
(74644400, 'Psi-Reflector', '念动力反射者', 'サイキック・リフレクター', 'Tuner Monster', 'Psychic', 'DARK', 1, 400, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。除「念动力反射者」外的1张「爆裂模式」或者有那个卡名记述的卡从卡组加入手卡。 ②：把手卡1张「爆裂模式」给对方观看，以「念动力反射者」以外的有「爆裂模式」的卡名记述的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤，那个等级上升最多4星。'),
(4230620, 'Psi-Station', '念动力休整', 'サイキックブレイク', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '念动力族怪兽召唤成功时，可以支付500基本分把那1只怪兽的等级上升1星，攻击力上升300。'),
(26523337, 'Psiics, Moonlight of the Ghoti', '游魊之月夜 赛克斯', 'ゴーティスの月夜サイクス', 'Effect Monster', 'Fish', 'WATER', 6, 2400, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「魊影的月夜 赛克斯」以外的1只鱼族怪兽加入手卡。那之后，自己的手卡·场上（表侧表示）1只鱼族怪兽除外。 ②：这张卡被除外的场合，从自己的手卡·场上（表侧表示）·墓地把「魊影的月夜 赛克斯」以外的1只鱼族怪兽除外才能发动。这张卡特殊召唤。'),
(51053997, 'PSY-Frame Accelerator', '精神骨架加速器', 'PSYフレーム・アクセラレーター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，支付500基本分，以自己场上1只「PSY骨架」怪兽为对象才能发动。那只怪兽直到下次的自己准备阶段除外。 ②：1回合1次，这张卡以外的自己场上的表侧表示的「PSY骨架」卡因战斗以外从场上离开的场合才能发动。从手卡把1只「PSY骨架」怪兽特殊召唤。'),
(575512, 'PSY-Frame Circuit', '精神骨架回路', 'PSYフレーム・サーキット', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上有「PSY骨架」怪兽特殊召唤的场合才能发动。只用自己场上的「PSY骨架」怪兽为同调素材作同调召唤。 ②：自己的「PSY骨架」怪兽和对方怪兽进行战斗的伤害步骤开始时，把手卡1只「PSY骨架」怪兽丢弃才能发动。那只进行战斗的自己怪兽的攻击力直到回合结束时上升因为这个效果发动而丢弃的怪兽的攻击力数值。'),
(49036338, 'PSY-Frame Driver', '精神骨架 驱动者', 'PSYフレーム・ドライバー', 'Normal Monster', 'Psychic', 'LIGHT', 6, 2500, NULL, '操纵电击的念动力战士。驱使自律型增幅器「PSY骨架」，对治安部队发动强袭。那个姿态，确实就如电光石火一般。'),
(43266605, 'PSY-Frame Multi-Threader', '精神骨架 多线处理者', 'PSYフレーム・マルチスレッダー', 'Effect Monster', 'Psychic', 'LIGHT', 6, NULL, 2500, '「PSY骨架多线人」的③的效果1回合只能使用1次。 ①：这张卡只要在手卡·墓地存在，当作「PSY骨架驱动者」使用。 ②：自己场上的「PSY骨架」卡被战斗·效果破坏的场合，可以作为代替把手卡的这张卡丢弃。 ③：这张卡在墓地存在，自己场上有「PSY骨架」调整特殊召唤的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(36970611, 'PSY-Frame Overload', '精神骨架过载', 'PSYフレーム・オーバーロード', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，从自己手卡以及自己场上的表侧表示怪兽之中把1只「PSY骨架」怪兽除外，以场上1张卡为对象才能把这个效果发动。那张卡里侧表示除外。 ②：把墓地的这张卡除外才能发动。从卡组把「PSY骨架超载」以外的1张「PSY骨架」卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(75425043, 'PSY-Framegear Alpha', '精神骨架装备 阿尔法', 'PSYフレームギア・α', 'Tuner Monster', 'Psychic', 'LIGHT', 1, 500, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：自己场上没有怪兽存在，对方把怪兽召唤·特殊召唤时才能发动。选手卡的这张卡和自己的手卡·卡组·墓地1只「PSY骨架驱动者」特殊召唤，从卡组把「PSY骨架装备·α」以外的1张「PSY骨架」卡加入手卡。这个效果特殊召唤的怪兽全部在结束阶段除外。'),
(2810642, 'PSY-Framegear Beta', '精神骨架装备 贝塔', 'PSYフレームギア・β', 'Tuner Monster', 'Psychic', 'LIGHT', 1, 700, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：自己场上没有怪兽存在，对方怪兽的攻击宣言时才能发动。选手卡的这张卡和自己的手卡·卡组·墓地1只「PSY骨架驱动者」特殊召唤，那只攻击怪兽破坏。那之后，战斗阶段结束。这个效果特殊召唤的怪兽全部在结束阶段除外。'),
(74203495, 'PSY-Framegear Delta', '精神骨架装备 德尔塔', 'PSYフレームギア・δ', 'Tuner Monster', 'Psychic', 'LIGHT', 2, 1200, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：自己场上没有怪兽存在，对方的魔法卡发动时才能发动。选手卡的这张卡和自己的手卡·卡组·墓地1只「PSY骨架驱动者」特殊召唤，那个发动无效并破坏。这个效果特殊召唤的怪兽全部在结束阶段除外。'),
(1697104, 'PSY-Framegear Epsilon', '精神骨架装备 伊普西隆', 'PSYフレームギア・ε', 'Tuner Monster', 'Psychic', 'LIGHT', 2, 1500, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：自己场上没有怪兽存在，对方的陷阱卡发动时才能发动。选手卡的这张卡和自己的手卡·卡组·墓地1只「PSY骨架驱动者」特殊召唤，那个发动无效并破坏。这个效果特殊召唤的怪兽全部在结束阶段除外。'),
(38814750, 'PSY-Framegear Gamma', '精神骨架装备 伽马', 'PSYフレームギア・γ', 'Tuner Monster', 'Psychic', 'LIGHT', 2, 1000, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：自己场上没有怪兽存在，对方怪兽的效果发动时才能发动。选手卡的这张卡和自己的手卡·卡组·墓地1只「PSY骨架驱动者」特殊召唤，那个发动无效并破坏。这个效果特殊召唤的怪兽全部在结束阶段除外。'),
(8802510, 'PSY-Framelord Lambda', '精神骨架装载王 兰木达', 'PSYフレームロード・Λ', 'Link Monster', 'Psychic', 'LIGHT', NULL, 1700, NULL, '衍生物以外的怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己在自己场上有怪兽存在的场合也能把手卡的「PSY骨架装备」怪兽的效果发动。 ②：这张卡已在怪兽区域存在的状态，这张卡以外的自己场上的表侧表示的念动力族怪兽被除外的场合才能发动。这个回合的结束阶段，从卡组把1张「PSY骨架」卡加入手卡。'),
(74586817, 'PSY-Framelord Omega', '精神骨架装载王 欧米伽', 'PSYフレームロード・Ω', 'Synchro Monster', 'Psychic', 'LIGHT', 8, 2800, 2200, '调整＋调整以外的怪兽1只以上 ①：1回合1次，自己·对方的主要阶段才能发动。对方手卡随机选1张，那张卡和表侧表示的这张卡直到下次的自己准备阶段表侧除外。 ②：对方准备阶段，以自己或对方的除外状态的1张卡为对象才能发动。那张卡回到墓地。 ③：这张卡在墓地存在的场合，以自己或对方的墓地1张其他卡为对象才能发动。那张卡和这张卡回到卡组。'),
(37192109, 'PSY-Framelord Zeta', '精神骨架装载王 截塔', 'PSYフレームロード・Ζ', 'Synchro Monster', 'Psychic', 'LIGHT', 7, 2500, 1800, '调整＋调整以外的怪兽1只以上 ①：1回合1次，以对方场上1只特殊召唤的表侧攻击表示怪兽为对象才能发动。那只怪兽和场上的这张卡直到下次的自己准备阶段除外。这个效果在对方回合也能发动。 ②：这张卡在墓地存在的场合，以这张卡以外的自己墓地1张「PSY骨架」卡为对象才能发动。这张卡回到额外卡组，作为对象的卡加入手卡。'),
(84453939, 'Psychic Ace', '念力王牌机师', 'サイコ・エース', 'Effect Monster', 'Psychic', 'DARK', 2, 1000, NULL, '①：怪兽区域的这张卡被解放的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(16238373, 'Psychic Arsenal', '大念力兵工厂', '大電脳兵廠', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只念动力族怪兽为对象，支付那个等级×200基本分才能发动。比那只怪兽等级高并持有相同属性的1只机械族怪兽从卡组加入手卡。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以自己的除外状态的念动力族怪兽和机械族怪兽各1只为对象才能发动。那之内的1只回到卡组最下面，另1只加入手卡。'),
(75539614, 'Psychic Blade', '念力宝剑', 'サイコ・ブレイド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「念力宝剑」在1回合只能发动1张。支付100的倍数的基本分才能把这张卡发动（最多2000）。 ①：装备怪兽的攻击力·守备力上升因为这张卡发动而支付的基本分数值。'),
(88139289, 'Psychic Blaster Mk-II', '念力枪手Mk－Ⅱ', 'サイコガンナーMk－Ⅱ', 'Synchro Monster', 'Psychic', 'EARTH', 9, 3200, 2700, '念动力族调整＋调整以外的念动力族怪兽1只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己或对方的除外状态的1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。 ②：自己·对方的主要阶段，从自己墓地把1只怪兽除外，以场上1只其他的表侧表示怪兽为对象才能发动。那只怪兽除外。那之后，自己基本分回复除外的怪兽的原本攻击力的数值。'),
(65471349, 'Psychic Bounder', '魔镜导士 念界反弹者', '魔鏡導士サイコ・バウンダー', 'Effect Monster', 'Machine', 'LIGHT', 4, 1700, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。把1只「人造人-念力震慑者」或者1张有那个卡名记述的魔法·陷阱卡从卡组加入手卡。 ②：这张卡以外的自己怪兽被对方怪兽攻击的伤害计算前才能发动。攻击怪兽和这张卡破坏。'),
(21454943, 'Psychic Commander', '念力指挥官', 'サイコ・コマンダー', 'Tuner Monster', 'Psychic', 'EARTH', 3, 1400, 800, '自己场上存在的念动力族怪兽进行战斗的场合，那个伤害步骤时支付100的倍数的基本分才能发动（最多500）。直到这个回合的结束阶段时，进行战斗的1只对方怪兽的攻击力·守备力下降支付的数值。'),
(77600660, 'Psychic Emperor', '念力帝皇', 'サイコ・エンペラー', 'Effect Monster', 'Psychic', 'LIGHT', 6, 2400, 1000, '这张卡召唤·特殊召唤成功时，自己墓地存在的念动力族怪兽每有1只，自己回复500基本分。'),
(60465049, 'Psychic End Punisher', '念力终焉处刑者', 'サイコ・エンド・パニッシャー', 'Synchro Monster', 'Psychic', 'LIGHT', 11, 3500, 3500, '调整＋调整以外的怪兽1只以上 ①：自己基本分是对方基本分以下的场合，同调召唤的这张卡不受对方发动的效果影响。 ②：1回合1次，支付1000基本分，以自己场上1只怪兽和对方场上1张卡为对象才能发动。那些卡除外。 ③：自己·对方的战斗阶段开始时才能发动。这张卡的攻击力上升双方基本分差的数值。'),
(9322133, 'Psychic Eraser Laser', '念力抹除光', 'サイコ・イレイザー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：选从额外卡组特殊召唤的对方场上1只怪兽送去墓地。那之后，对方基本分回复送去墓地的怪兽的原本攻击力和原本守备力之内较高方的数值。'),
(11047543, 'Psychic Feel Zone', '念力感知区', 'サイコ・フィール・ゾーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '让从游戏中除外的自己1只念动力族的调整和1只调整以外的念动力族怪兽回到墓地，和那个等级合计相同等级的1只念动力族的同调怪兽从额外卡组表侧守备表示特殊召唤。'),
(26773909, 'Psychic Fervor', '才呼粉身', '才呼粉身', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的战斗阶段以自己场上1只表侧表示怪兽为对象才能发动。自己失去那只怪兽的攻击力数值的基本分，那只怪兽的攻击力直到回合结束时变成2倍。这张卡发动的回合，作为对象的怪兽不能直接攻击。'),
(52430902, 'Psychic Jumper', '念力跳跃者', 'サイコジャンパー', 'Tuner Monster', 'Psychic', 'EARTH', 2, 100, 1500, '支付1000基本分并选择对方场上表侧表示存在的1只怪兽，那只怪兽和「念力跳跃者」以外的自己场上表侧表示存在的1只念动力族怪兽的控制权交换。选择的怪兽在这个回合不能作表示形式的改变。这个效果1回合只能使用1次。'),
(7892180, 'Psychic Kappa', '念力河童', 'サイコ・カッパー', 'Normal Monster', 'Aqua', 'WATER', 2, 400, 1000, '能使用多种超能力避开攻击的河童。'),
(45379225, 'Psychic Lifetrancer', '念力健能转换者', 'サイコ・ヘルストランサー', 'Synchro Monster', 'Psychic', 'EARTH', 7, 2400, 2000, '调整＋调整以外的怪兽1只以上 把自己墓地存在的1只念动力族怪兽从游戏中除外发动。自己回复1200基本分。这个效果1回合只能使用1次。'),
(91870448, 'Psychic Megacyber', '念力电子巨人', 'サイコ・ギガサイバー', 'Effect Monster', 'Machine', 'DARK', 6, 2200, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：对方场上的魔法·陷阱卡数量比自己场上的魔法·陷阱卡多的场合，这张卡可以从手卡特殊召唤。 ②：自己场上有「人造人-念力震慑者」存在，这张卡向对方的效果怪兽攻击宣言时，把这张卡解放才能发动。那只对方怪兽当作永续陷阱卡使用在对方的魔法与陷阱区域表侧表示放置。'),
(7582066, 'Psychic Nightmare', '念力恶魔', 'サイコ・デビル', 'Synchro Monster', 'Psychic', 'WIND', 6, 2400, 1800, '调整＋调整以外的念动力族怪兽1只以上 ①：1回合1次，自己主要阶段才能发动。对方手卡随机选1张，对那张卡的种类（怪兽·魔法·陷阱）作猜测。猜中的场合，这张卡的攻击力直到下次的对方回合的结束时上升1000。'),
(70659412, 'Psychic Omnibuster', '念力汇总破坏者', NULL, 'Synchro Monster', 'Psychic', 'WIND', 7, 2500, 2000, '调整＋调整以外的念动力族怪兽1只以上 对方把卡的效果在场上发动时（伤害步骤除外）：可以支付2000基本分，宣言1个卡的种类（怪兽·魔法·陷阱）（每个卡的种类1回合只能为让「念力汇总破坏者」的这个效果发动宣言1次）；随机把对方1张手卡确认，那是宣言种类的场合，适用以下效果。 ●这个回合，这张卡不会被宣言种类的卡的效果破坏。 ●确认的卡直到结束阶段以表侧除外。'),
(82633308, 'Psychic Overload', '念力聚能', 'サイコ・チャージ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的3只念动力族怪兽，加入卡组洗切。那之后，从自己卡组抽2张卡。'),
(25401880, 'Psychic Path', '念力通道', 'サイコパス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付800基本分，以除外的最多2只自己的念动力族怪兽为对象才能发动。那些怪兽加入手卡。'),
(70843274, 'Psychic Processor', '念力处理器', 'サイコ・プロセッサー', 'Effect Monster', 'Psychic', 'DARK', 3, NULL, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：把场上的这张卡除外才能发动。从手卡把最多2只机械族·念动力族·电子界族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合可以直接攻击。 ②：这张卡被除外的下个回合的准备阶段才能发动。除外状态的这张卡加入手卡。'),
(3146695, 'Psychic Reactor', '念力反应器', 'サイコ・リアクター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有念动力族怪兽表侧表示存在的场合才能发动。自己场上表侧表示存在的念动力族怪兽在这个回合和对方怪兽进行过战斗时，把那只念动力族怪兽和对方怪兽从游戏中除外。'),
(21488686, 'Psychic Rejuvenation', '念力治愈', 'サイコ・ヒーリング', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的念动力族怪兽每有1只，自己回复1000基本分。'),
(53154400, 'Psychic Rover', '念力流浪者', 'サイコ・ローヴァー', 'Effect Monster', 'Psychic', 'DARK', 2, NULL, 700, '①：这张卡特殊召唤成功的场合才能发动。掷1次骰子。1·6出现的场合，选场上最多2张卡破坏。 ②：这张卡被送去墓地的场合才能发动。掷1次骰子。2～5出现的场合，这张卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不能从额外卡组把怪兽特殊召唤。'),
(72563071, 'Psychic Shockwave', '念力震撼波', 'サイコ・ショックウェーブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方把陷阱卡发动时，从手卡丢弃1张魔法·陷阱卡才能发动。从卡组把1只机械族·暗属性·6星怪兽特殊召唤。'),
(58453942, 'Psychic Snail', '念力蜗牛', 'サイコ・ウォールド', 'Effect Monster', 'Psychic', 'EARTH', 4, 1900, 1200, '支付800基本分发动。自己场上表侧表示存在的1只念动力族怪兽在同1次的战斗阶段中可以作2次攻击。这个效果发动的回合这张卡不能攻击。'),
(33323657, 'Psychic Soul', '念力之魂', 'サイコ・ソウル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只念动力族怪兽解放发动。自己回复解放怪兽的等级×300的数值的基本分。'),
(92346415, 'Psychic Sword', '念力剑', 'サイコ・ソード', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '念动力族怪兽才能装备。自己基本分比对方低的场合，装备怪兽的攻击力上升那个数值（最多2000）。'),
(30227494, 'Psychic Tracker', '念力追踪者', 'サイコトラッカー', 'Effect Monster', 'Psychic', 'EARTH', 3, 1600, 600, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「念力循轨人」以外的3星怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：这张卡为同调素材的同调怪兽的攻击力上升600。'),
(55673611, 'Psychic Trigger', '念力触发器', 'サイコ・トリガー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己基本分比对方低的场合才能发动。把自己墓地存在的2只念动力族怪兽从游戏中除外，从自己卡组抽2张卡。'),
(3891471, 'Psychic Tuning', '念力调整', 'サイコ・チューン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只念动力族怪兽，攻击表示特殊召唤。这个效果特殊召唤的怪兽当作调整使用。这张卡不在场上存在时，那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。这张卡被送去墓地时，自己受到这张卡的效果特殊召唤的怪兽等级×400的数值的伤害。'),
(80681226, 'Psychic Wave', '念动力波', 'サイキック・ウェーブ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有机械族怪兽存在的场合，从手卡·卡组把1只「人造人-念力震慑者」送去墓地才能发动。给与对方600伤害。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只机械族怪兽为对象才能发动。从卡组把1只「人造人」怪兽送去墓地，作为对象的怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(3233859, 'Psychic Wheeleder', '念力轮式装载机', 'サイコウィールダー', 'Tuner Monster', 'Psychic', 'EARTH', 3, 600, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「念力控轮人」以外的3星怪兽存在的场合，这张卡可以从手卡守备表示特殊召唤。 ②：这张卡作为同调怪兽的同调素材送去墓地的场合，以持有比那只同调怪兽低的攻击力的场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(32180819, 'Psychokinesis', '最古式念导', '最古式念導', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有念动力族怪兽表侧表示存在的场合才能发动。场上1张卡破坏，自己受到1000分伤害。'),
(35089369, 'Pulao, Wind of the Yang Zing', '风龙星－蒲牢', '風竜星－ホロウ', 'Effect Monster', 'Wyrm', 'WIND', 1, NULL, 1800, '「风龙星-蒲牢」的①的效果1回合只能使用1次。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「风龙星-蒲牢」以外的1只「龙星」怪兽攻击表示特殊召唤。 ②：1回合1次，对方的主要阶段以及战斗阶段才能发动。只用自己场上的「龙星」怪兽为同调素材作同调召唤。 ③：这张卡为同调素材的同调怪兽不受魔法卡的效果影响。'),
(34717238, 'Pulling the Rug', '叠返', '畳返し', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '召唤成功时发动的效果怪兽的发动和效果无效，那只怪兽破坏。'),
(58464739, 'Pulse Mines', '脉冲炸弹', 'パルス・ボム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有机械族怪兽存在的场合才能发动。对方场上有攻击表示怪兽存在的场合，那些怪兽全部变成守备表示。直到回合结束时，对方场上有怪兽召唤·特殊召唤的场合，那些怪兽变成守备表示。'),
(14512825, 'Pumpkin Carriage', '南瓜马车', 'カボチャの馬車', 'Effect Monster', 'Plant', 'EARTH', 3, NULL, 300, '①：只要这张卡在怪兽区域存在，自己的「灰姑娘」可以直接攻击。 ②：只要这张卡在怪兽区域存在，自己场上的「急流山的金宫」不会被效果破坏，不会成为对方的效果的对象。'),
(29155212, 'Pumpking the King of Ghosts', '幽灵王-南瓜王-', 'ゴースト王－パンプキング－', 'Effect Monster', 'Zombie', 'DARK', 6, 1800, 2000, '只要「暗晦之城」在场上表侧表示存在，这张卡的攻击力·守备力上升100。此外，每次自己的准备阶段再上升100。这个效果持续到自己的第4个准备阶段。'),
(17601919, 'Pumprincess the Princess of Ghosts', '幽灵姬-南瓜公主-', 'ゴースト姫－パンプリンセス－', 'Effect Monster', 'Zombie', 'DARK', 3, 900, 1000, '这张卡在怪兽卡区域上被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱卡区域表侧表示放置。这个效果当作永续魔法卡使用的场合，每次双方的准备阶段给这张卡放置1个南瓜指示物。对方场上的全部怪兽的攻击力·守备力下降当作永续魔法卡使用的这张卡放置的南瓜指示物数量×100的数值。'),
(31077447, 'Punch-in-the-Box', '吓人箱', 'びっくり箱', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有怪兽2只以上存在的场合，对方怪兽的攻击宣言时以那1只怪兽为对象才能发动。那次攻击无效，选那只怪兽以外的对方场上1只怪兽送去墓地。那之后，作为对象的怪兽的攻击力下降送去墓地的怪兽的攻击力和守备力之内较高方的数值。'),
(74703140, 'Punished Eagle', '裁决之鹰', '裁きの鷹', 'Fusion Monster', 'Winged Beast', 'WIND', 6, 2100, 1800, '「苍翼冠鸟」＋「胖鸡」'),
(19959563, 'Punishment Dragon', '惩戒之龙', '戒めの龍', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 2600, '这张卡不能通常召唤。自己的除外状态的「光道」怪兽是4种类以上的场合才能特殊召唤。 ①：自己·对方回合1次，支付1000基本分才能发动。「光道」怪兽以外的双方的墓地·除外状态（表侧）的卡全部回到卡组。 ②：1回合1次，自己的「光道」怪兽的效果发动的场合发动。从自己卡组上面把4张卡送去墓地。'),
(76442347, 'Puny Penguin', '子型企鹅', '子型ペンギン', 'Effect Monster', 'Aqua', 'WATER', 1, 400, 200, '反转过的这张卡被送去墓地时，从自己墓地选择「子型企鹅」以外的1只名字带有「企鹅」的怪兽表侧攻击表示或者里侧守备表示特殊召唤。'),
(3167573, 'Puppet King', '人偶国王', 'パペット・キング', 'Effect Monster', 'Warrior', 'EARTH', 7, 2800, 2600, '①：对方用抽卡以外的方法从卡组把怪兽加入手卡时才能发动。这张卡从手卡特殊召唤。 ②：这张卡的①的效果特殊召唤成功的场合，下次的自己回合的结束阶段发动。这张卡破坏。'),
(41442341, 'Puppet Master', '操控死灵的傀儡大师', '死霊操りしパペットマスター', 'Effect Monster', 'Fiend', 'DARK', 6, NULL, NULL, '①：这张卡上级召唤成功时，支付2000基本分，以自己墓地2只恶魔族怪兽为对象才能发动。那些恶魔族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(32875265, 'Puppet Parade', '傀儡葬仪－傀偶游行', '傀儡葬儀－パペット・パレード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，把最多有那个相差数量的「机关傀儡」怪兽从卡组特殊召唤（同名卡最多1张）。自己基本分比对方少2000以上的场合，可以再从卡组选1张「升阶魔法」通常魔法卡在自己的魔法与陷阱区域盖放。这张卡的发动后，直到回合结束时自己不是「机关傀儡」怪兽不能特殊召唤。'),
(89839552, 'Puppet Pawn', '人偶兵卒', 'パペット・ポーン', 'Effect Monster', 'Warrior', 'EARTH', 3, 800, 1200, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡可以直接攻击。 ②：这张卡给与对方战斗伤害时才能发动。从卡组把1张「升变」加入手卡。 ③：把墓地的这张卡除外才能发动。从卡组把「人偶兵卒」以外的1只战士族·地属性怪兽加入手卡。那之后，对方可以从自身卡组把1只怪兽加入手卡。'),
(51119924, 'Puppet Plant', '傀儡植物', 'パペット・プラント', 'Effect Monster', 'Plant', 'EARTH', 3, 1000, 1000, '把这张卡从手卡丢弃去墓地。直到这个回合的结束阶段时，得到对方场上表侧表示存在的1只战士族或者魔法师族怪兽的控制权。'),
(15001619, 'Puppet Queen', '人偶王后', 'パペット・クィーン', 'Effect Monster', 'Warrior', 'EARTH', 6, 2200, 2500, '这个卡名的②的效果1回合只能使用1次。 ①：对方用抽卡以外的方法从卡组把怪兽加入手卡时才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只战士族·地属性·7星怪兽特殊召唤。这个效果把「人偶国王」特殊召唤的场合，自己场上的全部战士族·地属性怪兽的攻击力直到下个回合的结束时上升1000。'),
(1969506, 'Puppet Ritual', '傀儡仪式', '傀儡儀式－パペット・リチューアル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己基本分比对方少2000以上的场合才能发动。从自己墓地选择2只名字带有「机关傀儡」的8星怪兽特殊召唤。「傀儡仪式」在1回合只能发动1张，这张卡发动的回合，自己不能进行战斗阶段。'),
(77590412, 'Puppet Rook', '人偶城堡', 'パペット・ルーク', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 1800, '①：这张卡召唤成功时才能发动。这张卡变成守备表示，从卡组把1只战士族·地属性怪兽送去墓地。 ②：只要这张卡在怪兽区域存在，可以攻击的对方怪兽必须向这张卡作出攻击。 ③：1回合1次，这张卡被选择作为攻击对象时，以自己墓地1只6星以上的战士族·地属性怪兽为对象才能发动。场上的这张卡送去墓地，作为对象的怪兽特殊召唤。那之后，攻击对象转移为那只怪兽。'),
(53323475, 'Puppet Shark', '傀儡风仪－傀偶鲨鱼', '傀儡流儀－パペット・シャーク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上1个超量素材取除，从自己卡组上面把4张卡翻开，从那之中选1张。那张卡种类的以下效果适用。剩下的卡用原本的顺序回到卡组上面。 ●怪兽·魔法：选的卡加入手卡。 ●陷阱：选的卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(37038993, 'Puralis, the Purple Pyrotile', '焰紫龙 巨火虫', '焔紫竜ピュラリス', 'Synchro Tuner Monster', 'Reptile', 'FIRE', 2, 800, 1400, '调整＋调整以外的怪兽1只 ①：这张卡从场上送去墓地的场合发动。对方场上的全部怪兽的攻击力下降500。'),
(64161630, 'Purge Ray', '净化光', 'パージ・レイ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只超量怪兽解放才能发动。这个回合的结束阶段时，和解放的怪兽相同种族而阶级低1阶的1只名字带有「No.」的怪兽从额外卡组特殊召唤。'),
(48461764, 'Purple Poison Magician', '紫毒的魔术师', '紫毒の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 4, 1200, 2100, '这张卡在规则上也当作「融合龙」卡使用。 ①：这张卡被战斗·效果破坏的场合，以场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(25550531, 'Purrely', '皮尔莉', 'ピュアリィ', 'Effect Monster', 'Fairy', 'LIGHT', 1, 100, 100, '①：这张卡召唤·特殊召唤的场合才能发动。从自己卡组上面把3张卡翻开。可以从那之中选1张「纯爱妖精」魔法·陷阱卡加入手卡。剩下的卡用喜欢的顺序回到卡组下面。 ②：1回合1次，自己主要阶段才能发动。手卡1张「纯爱妖精」速攻魔法卡给对方观看，把有那个卡名记述的1只超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤，把给人观看的卡作为那只超量怪兽的超量素材。'),
(55584558, 'Purrely Delicious Memory', '皮尔莉・美味回忆', 'ピュアリィ・デリシャスメモリー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：选场上1只怪兽，那只怪兽直到下个回合的结束时不会被战斗破坏。并且，可以再让以下效果适用。 ●选自己1张手卡丢弃，从卡组把1只1星「纯爱妖精」怪兽特殊召唤。 ②：持有这张卡作为素材中的「纯爱妖精」超量怪兽得到以下效果。 ●这张卡的攻击力·守备力上升这张卡的超量素材数量×300。'),
(82105704, 'Purrely Happy Memory', '皮尔莉・快乐回忆', 'ピュアリィ・ハッピーメモリー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：选场上1张卡，那张卡直到下个回合的结束时只有1次不会被效果破坏。并且，可以再让以下效果适用。 ●选自己1张手卡丢弃，从卡组把1只1星「纯爱妖精」怪兽特殊召唤。 ②：持有这张卡作为素材中的「纯爱妖精」超量怪兽得到以下效果。 ●这张卡在同1次的战斗阶段中可以向怪兽作出最多有这张卡持有作为超量素材中的「纯爱妖精快乐回忆」数量＋1次的攻击。'),
(29599813, 'Purrely Pretty Memory', '皮尔莉・漂亮回忆', 'ピュアリィ・プリティメモリー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：双方回复1000基本分。并且，可以再让以下效果适用。 ●选自己1张手卡丢弃，从卡组把1只1星「纯爱妖精」怪兽特殊召唤。 ②：有这张卡在作为超量素材中的「纯爱妖精」超量怪兽得到以下效果。 ●1回合1次，把自己场上1张其他卡送去墓地，以对方场上1张卡为对象才能发动。那张卡作为这张卡的超量素材。'),
(10780049, 'Purrely Sharely!?', '皮尔莉分享莉！？', 'ピュアリィ・シェアリィ！？', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「纯爱妖精」超量怪兽为对象才能发动。从卡组把1只1星「纯爱妖精」怪兽效果无效特殊召唤，和作为对象的怪兽是属性不同并是阶级相同的1只「纯爱妖精」超量怪兽在那只特殊召唤的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。那之后，以下效果可以适用。 ●从卡组选1张给作为对象的怪兽作为超量素材中的「纯爱妖精」速攻魔法卡的同名卡作为那只超量召唤的怪兽的超量素材。'),
(21347668, 'Purrely Sleepy Memory', '皮尔莉・困倦回忆', 'ピュアリィ・スリーピィメモリー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：这个回合，自己受到的战斗·效果伤害只有1次变成0。并且，可以再让以下效果适用。 ●选自己1张手卡丢弃，从卡组把1只1星「纯爱妖精」怪兽特殊召唤。 ②：持有这张卡作为素材中的「纯爱妖精」超量怪兽得到以下效果。 ●对方准备阶段才能发动。自己从卡组抽1张。'),
(82983267, 'Purrelyeap!?', '皮尔莉穿越！？', 'ピュアリィープ！？', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「纯爱妖精」超量怪兽为对象才能发动。和那只自己怪兽阶级不同的1只「纯爱妖精」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽在下个回合的结束阶段回到持有者的额外卡组。 ②：把墓地的这张卡除外，以自己墓地最多3只「纯爱妖精」怪兽为对象才能发动。那些怪兽回到卡组。'),
(79933029, 'Purrelyly', '皮尔莉・莉莉', 'ピュアリィ・リリィ', 'Effect Monster', 'Fairy', 'DARK', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把速攻魔法卡以外的1张「纯爱妖精」卡加入手卡。 ②：以自己墓地1张「纯爱妖精」速攻魔法卡为对象才能发动。把有那个卡名记述的1只超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤，把作为对象的卡在那只超量怪兽下面重叠作为超量素材。'),
(27870033, 'Pursuit Chaser', '追缉巡逻机', 'チェイス・スカッド', 'Effect Monster', 'Machine', 'EARTH', 3, 1400, 600, '场上守备表示存在的怪兽被战斗破坏送去墓地时，给与对方基本分500分伤害。'),
(78942513, 'Purushaddoll Aeon', '魂源影依永劫', '魂源への影劫回帰', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「影依」怪兽为对象才能发动。从手卡把1张「影依」卡送去墓地。作为对象的怪兽攻击力·守备力上升1000，结束阶段变成里侧守备表示。'),
(85101097, 'Putrid Pudding Body Buddies', '布丁队', 'プリン隊', 'Effect Monster', 'Fiend', 'WATER', 1, 300, 300, '这张卡不能作为融合·同调·超量召唤的素材。 ①：只要这张卡在怪兽区域存在，这张卡不能解放。 ②：自己结束阶段以自己的灵摆区域1张卡为对象才能发动。那张卡破坏，这张卡的控制权移给对方。 ③：自己准备阶段发动。自己受到300伤害。'),
(30585393, 'Puzzle Reborn', '苏生拼组', 'リボーン・パズル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '只让自己场上的怪兽1只被卡的效果破坏的场合，选择那1只才能发动。选择的怪兽在自己场上特殊召唤。'),
(84271823, 'Puzzlomino, the Drop-n-Deleter', '下落消除之拼图多连块', '落消しのパズロミノ', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 1300, NULL, '等级不同的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡已在怪兽区域存在的状态，这张卡所连接区有怪兽表侧表示特殊召唤的场合，宣言1～8的任意等级才能发动。那只怪兽直到回合结束时变成宣言的等级。 ②：从自己和对方的场上以相同等级的怪兽各1只为对象才能发动。那些怪兽破坏。'),
(76754619, 'Pyramid Energy', '金字塔能量', 'ピラミッドパワー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择下面的1个效果发动。 ●自己的场上全部表侧表示存在的怪兽直到回合结束前攻击力上升200。 ●自己的场上全部表侧表示存在的怪兽直到回合结束前守备力上升500。'),
(53569894, 'Pyramid of Light', '光之金字塔', '光のピラミッド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的这张卡从场上离开的场合，自己场上存在的「斯芬克斯·安德鲁」和「斯芬克斯·迪蕾雅」破坏并从游戏中除外。'),
(66835946, 'Pyramid of Wonders', '奇迹之金字塔', '奇跡のピラミッド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的不死族怪兽的攻击力上升对方场上存在的怪兽数量×200的数值。自己场上表侧表示存在的不死族怪兽1只被破坏的场合，可以作为代替把这张卡送去墓地。'),
(77044671, 'Pyramid Turtle', '金字塔龟', 'ピラミッド・タートル', 'Effect Monster', 'Zombie', 'EARTH', 4, 1200, 1400, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只守备力2000以下的不死族怪兽特殊召唤。'),
(48228390, 'Pyrite Knight', '黄铁之愚骑士', '黄鉄の愚騎士', 'Effect Monster', 'Warrior', 'EARTH', 5, 2000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，以「黄铁之愚骑士」以外的自己场上1只地·炎属性的战士族怪兽为对象才能发动。那只怪兽回到手卡，这张卡特殊召唤。那之后，在对方场上把1只「黄铁衍生物」（战士族·炎·4星·攻0/守2000）守备表示特殊召唤。 ②：自己·对方的战斗阶段才能发动。从手卡把1只战士族怪兽特殊召唤。'),
(1082946, 'Pyro Clock of Destiny', '命运之火钟', '運命の火時計', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '1张卡的回合计算前进1回合。'),
(35842855, 'Pyrorex the Elemental Lord', '炎灵神 派罗雷克斯', '炎霊神パイロレクス', 'Effect Monster', 'Dinosaur', 'FIRE', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的炎属性怪兽是5只的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功时，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，双方玩家受到那只怪兽的原本攻击力一半数值的伤害。 ②：表侧表示的这张卡从场上离开的场合，下次的自己回合的战斗阶段跳过。'),
(61231400, 'Pyrotech Mech - Shiryu', '炎神机-紫龙', '炎神機－紫龍', 'Effect Monster', 'Pyro', 'FIRE', 8, 2900, 1800, '这张卡可以把1只怪兽解放作召唤。这个方法召唤的场合，自己在每次结束阶段受到1000分伤害。这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(55824220, 'Pyroxene Fusion', '辉石融合', '輝石融合', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡·自己场上把融合怪兽卡决定的融合素材怪兽送去墓地，把名字带有「宝石骑士」的那1只融合怪兽当作融合召唤从额外卡组特殊召唤。'),
(24635329, 'Qadshaddoll Keios', '圣影依 凯乌斯', '聖なる影 ケイウス', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 2, 900, 100, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡反转的场合才能发动。从手卡把1只「影依」怪兽表侧守备表示或者里侧守备表示特殊召唤。 ②：这张卡被效果送去墓地的场合才能发动。从手卡把1只「影依」怪兽送去墓地。这个回合中，以下效果适用。 ●自己场上的怪兽的攻击力·守备力上升这个效果送去墓地的怪兽的原本等级×100。'),
(86605515, 'Qardan the Clear-Sighted', '贤瑞官 卡尔丹', '賢瑞官カルダーン', 'Effect Monster', 'Fairy', 'EARTH', 4, 1400, 1000, '①：这张卡召唤时才能发动。从自己的手卡·墓地把1张永续陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。 ②：这张卡被送去墓地的场合才能发动。直到下个回合的结束时，自己场上的表侧表示的陷阱卡不会被对方的效果破坏。'),
(74725513, 'Qebehsenuef, Protection of Horus', '荷鲁斯的加护－克贝克塞努弗', 'ホルスの加護－ケベンセヌフ', 'Effect Monster', 'Winged Beast', 'EARTH', 8, 2500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有「王之棺」存在的场合，这张卡可以从墓地特殊召唤。 ②：这张卡在怪兽区域存在的状态，自己场上的其他卡因对方的效果从场上离开的场合才能发动。这个回合中，对方怪兽不能把「荷鲁斯」怪兽作为攻击对象，对方不能把场上的「荷鲁斯」怪兽作为效果的对象。'),
(20447641, 'Qlife''s End', '机壳的冻结', '機殻の凍結', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（机械族·地·4星·攻1800/守1000）在怪兽区域特殊召唤（不当作陷阱卡使用）。这个效果把这张卡特殊召唤的回合，自己场上的「机壳」魔法·陷阱卡不会被效果破坏。 ②：这张卡的效果特殊召唤的这张卡在「隐藏的机壳」怪兽上级召唤的场合，可以作为3只的数量解放。'),
(4450854, 'Qlimate Change', '隐藏的机壳', '隠されし機殻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「隐藏的机壳」在1回合只能发动1张。 ①：从自己的额外卡组把最多3只表侧表示的「机壳」灵摆怪兽加入手卡。'),
(91907707, 'Qliphort Carrier', '机壳档案 色欲', 'クリフォート・アーカイブ', 'Pendulum Effect Monster', 'Machine', 'EARTH', 6, 2400, 1000, '①：这张卡可以不用解放作召唤。 ②：特殊召唤或者不用解放作召唤的这张卡的等级变成4星，原本攻击力变成1800。 ③：通常召唤的这张卡不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ④：这张卡被解放的场合，以场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。'),
(87588741, 'Qliphort Cephalopod', '机壳存取 残酷', 'クリフォート・アクセス', 'Pendulum Effect Monster', 'Machine', 'EARTH', 7, 2800, 1000, '①：这张卡可以不用解放作召唤。 ②：特殊召唤或者不用解放作召唤的这张卡的等级变成4星，原本攻击力变成1800。 ③：通常召唤的这张卡不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ④：把「机壳」怪兽解放对这张卡的上级召唤成功时才能发动。对方墓地的怪兽数量比自己墓地的怪兽多的场合，自己回复那个相差×300基本分，给与对方那个数值的伤害。'),
(64496451, 'Qliphort Disk', '机壳磁盘 无感动', 'クリフォート・ディスク', 'Pendulum Effect Monster', 'Machine', 'EARTH', 7, 2800, 1000, '①：这张卡可以不用解放作召唤。 ②：特殊召唤或者不用解放作召唤的这张卡的等级变成4星，原本攻击力变成1800。 ③：通常召唤的这张卡不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ④：把「机壳」怪兽解放对这张卡的上级召唤成功时才能发动。从卡组把2只「机壳」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(22423493, 'Qliphort Genius', '机壳・盖尼乌斯', 'クリフォート・ゲニウス', 'Link Monster', 'Machine', 'EARTH', NULL, 1800, NULL, '机械族怪兽2只 ①：连接召唤的这张卡不受魔法·陷阱卡的效果影响，也不受这张卡以外的连接怪兽发动的效果影响。 ②：1回合1次，以这张卡以外的自己以及对方场上的表侧表示的卡各1张为对象才能发动。那2张卡的效果直到回合结束时无效。 ③：这张卡所连接区有怪兽2只同时特殊召唤时才能发动。从卡组把1只5星以上的机械族怪兽加入手卡。'),
(37991342, 'Qliphort Helix', '机壳基因组 贪欲', 'クリフォート・ゲノム', 'Pendulum Effect Monster', 'Machine', 'EARTH', 6, 2400, 1000, '①：这张卡可以不用解放作召唤。 ②：特殊召唤或者不用解放作召唤的这张卡的等级变成4星，原本攻击力变成1800。 ③：通常召唤的这张卡不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ④：这张卡被解放的场合，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(51194046, 'Qliphort Monolith', '机壳汇编器 不安定', 'クリフォート・アセンブラ', 'Pendulum Normal Monster', 'Machine', 'EARTH', 5, 2400, 1000, 'qliphoth.exe 中的 0x1i-666 确认到未处理的异常。 写入位置 0x00-000 时发生访问冲突。 您想忽略此错误并尝试继续吗? <Y/N>...[ ] ===CARNAGE=== 恶gn善iod道ru知能oy似no相yr们gn我a与s经i已do人G那 着doo活lfe远永rif就g吃n子i果r的b树o命t生t摘又n手a伸w他怕d恐n在a现'),
(65518099, 'Qliphort Scout', '机壳工具 丑恶', 'クリフォート・ツール', 'Pendulum Normal Monster', 'Machine', 'EARTH', 5, 1000, 2800, '正在准备以副本模式启动系统... C:\sophia\sefiroth.exe 执行中发生错误。 正在试图执行来自未知发布者的以下程序。 C:\tierra\qliphoth.exe 您想允许执行吗? <Y/N>...[Y] 以自律模式启动系统。'),
(90885155, 'Qliphort Shell', '机壳壳层 拒绝', 'クリフォート・シェル', 'Pendulum Effect Monster', 'Machine', 'EARTH', 8, 2800, 1000, '①：这张卡可以不用解放作召唤。 ②：特殊召唤或者不用解放作召唤的这张卡的等级变成4星，原本攻击力变成1800。 ③：通常召唤的这张卡不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ④：把「机壳」怪兽解放表侧表示上级召唤成功的场合，这张卡在同1次的战斗阶段中可以作2次攻击，向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(13073850, 'Qliphort Stealth', '机壳别名 愚钝', 'クリフォート・エイリアス', 'Pendulum Effect Monster', 'Machine', 'EARTH', 8, 2800, 1000, '①：这张卡可以不用解放作召唤。 ②：特殊召唤或者不用解放作召唤的这张卡的等级变成4星，原本攻击力变成1800。 ③：通常召唤的这张卡不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ④：把「机壳」怪兽解放对这张卡的上级召唤成功时，以场上1张卡为对象才能发动。那张卡回到持有者手卡。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。'),
(30845999, 'Qlipper Launch', '起动的机壳', '起動する機殻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的通常召唤的「机壳」怪兽直到回合结束时攻击力上升300，效果无效化，不受这张卡以外的魔法·陷阱卡的效果影响。'),
(84673574, 'QQ Enneagon', 'QQ九角怪', 'QQエニアゴン', 'Effect Monster', 'Dinosaur', 'FIRE', 9, 900, 900, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，把「QQ九角火龙」以外的手卡1只9星怪兽给对方观看才能发动。这张卡和给人观看的怪兽共2只守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是9阶以上的超量怪兽不能从额外卡组特殊召唤。 ②：有这张卡在作为超量素材中的9阶以上的超量怪兽得到以下效果。 ●这张卡的攻击力·守备力上升900。'),
(29296344, 'Quadborrel Dragon', '削短双枪管龙', 'ソーンヴァレル・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1000, NULL, '包含「弹丸」怪兽的龙族怪兽2只 这个卡名的效果1回合只能使用1次。 ①：丢弃1张手卡，以场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。这个效果把连接怪兽破坏的场合，可以再把最多有那个连接标记数量的「弹丸」怪兽从自己的手卡·墓地特殊召唤（同名卡最多1张）。这个效果的发动后，直到回合结束时自己不能把连接2以下的怪兽从额外卡组特殊召唤。'),
(16693934, 'Quadogmatika Beast', '凶教导之圣兽', '凶導の聖獣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的墓地·除外状态的1只怪兽为对象才能发动。把持有那只怪兽的攻击力以上的攻击力的1只额外卡组的怪兽或者卡组的「教导」怪兽送去墓地，作为对象的怪兽特殊召唤。这张卡的发动后，直到下次的自己回合的结束时自己不能从额外卡组把怪兽特殊召唤。'),
(40838625, 'Quaking Mirror Force', '沙尘防护罩 -尘埃之力-', '砂塵のバリア －ダスト・フォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方场上的攻击表示怪兽全部变成里侧守备表示。这个效果变成里侧守备表示的怪兽不能把表示形式变更。'),
(87772572, 'Quantum Cat', '量子猫', '量子猫', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：宣言种族和属性各1个才能把这张卡发动。这张卡发动后变成持有宣言的种族·属性的通常怪兽（4星·攻0/守2200）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。'),
(90519313, 'Quarantine', '检疫', '検疫', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己·对方的结束阶段以对方场上盖放的1张魔法·陷阱卡为对象才能把这个效果发动。把那张卡确认，回到原状。'),
(96470883, 'Queen Angel of Roses', '凛天使 蔷薇之女王', '凛天使クイーン・オブ・ローズ', 'Effect Monster', 'Plant', 'EARTH', 7, 2400, 1300, '这张卡可以把1只植物族怪兽解放表侧攻击表示上级召唤。自己的准备阶段时只有1次，场上表侧表示存在的1只攻击力最低的怪兽破坏。'),
(65033975, 'Queen Azamina', '圣徒妖主', 'アザミナの妖魔', 'Effect Monster', 'Illusion', 'DARK', 8, 2500, 2000, '这个卡名在规则上也当作「罪宝」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：自己的手卡·场上的这张卡被自己或对方发动的效果所送去墓地的场合或者所除外的场合才能发动。这张卡特殊召唤。 ②：自己的「蓟花」怪兽或「白森林」怪兽战斗破坏对方怪兽时，以自己墓地1张「罪宝」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(73081602, 'Queen Bird', '女王鸟', 'クイーン・バード', 'Normal Monster', 'Winged Beast', 'WIND', 5, 1200, 2000, '用巨大的嘴啄击敌人作为攻击手段。守备力很高。'),
(13302026, 'Queen Butterfly Danaus', '女王蝶 斑蝶', 'クイーン・バタフライ ダナウス', 'Effect Monster', 'Insect', 'WIND', 8, 2800, 1900, '这个卡名的效果1回合只能使用1次。 ①：这张卡是已通常召唤的场合，以自己墓地最多3只4星以下的昆虫族怪兽为对象才能发动。这张卡的攻击力变成0，作为对象的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果在对方回合也能发动。'),
(90726340, 'Queen Dragun Djinn', '龙魔人 女王龙', '竜魔人 クィーンドラグーン', 'XYZ Monster', 'Dragon', 'DARK', 4, 2200, 1200, '4星怪兽×2 只要这张卡在场上表侧表示存在，「龙魔人 龙骑士女王」以外的自己的龙族怪兽不会被战斗破坏。此外，1回合1次，可以把这张卡1个超量素材取除，选择自己墓地1只5星以上的龙族怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，这个回合那只怪兽不能攻击。'),
(4179849, 'Queen of Autumn Leaves', '红叶之女王', '紅葉の女王', 'Normal Monster', 'Plant', 'EARTH', 5, 1800, 1500, '生活在被红叶围绕的地方，绿树灵王的妃子。'),
(501000003, 'Queen of Fate - Eternia', NULL, NULL, 'Effect Monster', 'Fairy', 'LIGHT', 8, 2400, 2000, NULL),
(72162751, 'Queen of the Blazing Domain', '阳炎殿的君主', '陽炎殿の君主', 'Effect Monster', 'Pyro', 'DARK', 9, 3000, 2500, '这个卡名的①的效果1回合只能使用1次。 ①：以包含表侧表示的魔法·陷阱卡的自己场上最多2张卡为对象才能发动。那些卡破坏，这张卡从手卡特殊召唤。这个效果破坏的卡是1张的场合，这张卡在下个回合的结束阶段回到手卡。2张的场合，这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，从场上送去对方墓地的怪兽不去墓地而除外。 ②：场上的这张卡不会被效果破坏。'),
(45500495, 'Queen of Thorns', '地狱刺藤', 'ヘル・ブランブル', 'Synchro Monster', 'Plant', 'LIGHT', 6, 2200, 1800, '调整＋调整以外的植物族怪兽1只以上 只要这张卡在场上表侧表示存在，双方必须为从手卡把植物族怪兽以外的怪兽召唤·特殊召唤支付每1只1000基本分。'),
(71411377, 'Queen''s Bodyguard', '女王亲卫队', '女王親衛隊', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 1200, '只要这张卡在自己场上表侧表示存在，自己场上存在的名字带有「魅惑的女王」的怪兽不能被选择作为攻击对象。'),
(5901497, 'Queen''s Double', '女王的影武者', '女王の影武者', 'Effect Monster', 'Warrior', 'EARTH', 1, 350, 300, '这张卡可以直接攻击对方玩家。'),
(25652259, 'Queen''s Knight', '王后骑士', 'クィーンズ・ナイト', 'Normal Monster', 'Warrior', 'LIGHT', 4, 1500, 1600, '用优美的动作愚弄敌人，抓住对方的空隙快速发出攻击。'),
(58477767, 'Queen''s Pawn', '女王的选择', '女王の選択', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的名字带有「亚马逊」的怪兽战斗破坏对方怪兽送去墓地时才能发动。从自己卡组把1只4星以下的名字带有「亚马逊」的怪兽特殊召唤。'),
(38723936, 'Question', '谜题', 'クイズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动中，对方不能确认墓地里的卡。对方玩家猜发动「谜题」的玩家墓地最下面1张怪兽卡的名字。如果猜中，将被猜的怪兽卡除外。如果猜错，将此怪兽卡在其持有者的场上特殊召唤。'),
(45869829, 'Quick Booster', '速攻魔力增幅器', '速攻魔力増幅器', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '从自己墓地选择「速攻魔力增幅器」以外的1张速攻魔法卡回到卡组。此外，场上的这张卡被对方破坏送去墓地的场合，可以从卡组把「速攻魔力增幅器」以外的1张速攻魔法卡加入手卡。'),
(49479374, 'Quick Charger', '急速充电器', '急速充電器', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己墓地存在的2只4星以下的名字带有「电池人」的怪兽加入手卡。'),
(31443476, 'Quick Launch', '速攻轮转', 'クイック・リボルブ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从卡组把1只「弹丸」怪兽特殊召唤。这个效果特殊召唤的怪兽不能攻击，结束阶段破坏。'),
(11287364, 'Quick-Span Knight', '速攻扳手骑士', 'クイック・スパナイト', 'Tuner Monster', 'Machine', 'EARTH', 3, 1000, 800, '这张卡被同调怪兽的同调召唤使用送去墓地的场合，对方场上表侧表示存在的1只怪兽的攻击力下降500。'),
(20932152, 'Quickdraw Synchron', '快枪同步士', 'クイック・シンクロン', 'Tuner Monster', 'Machine', 'WIND', 5, 700, 1400, '这张卡可以作为「同调士」调整的代替而成为同调素材。把这张卡作为同调素材的场合，不是以「同调士」调整为素材的同调怪兽的同调召唤不能使用。 ①：这张卡可以把手卡1只怪兽送去墓地，从手卡特殊召唤。'),
(31980955, 'Quiet Life', '慢活族', 'スローライフ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上没有怪兽存在的场合，自己主要阶段1开始时才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，以下效果适用。 ●把怪兽通常召唤的玩家在那个回合不能把怪兽特殊召唤。 ●把怪兽特殊召唤的玩家在那个回合不能把怪兽通常召唤。'),
(27980138, 'Quill Pen of Gulldos', '翔鹏的羽毛笔', 'ガルドスの羽根ペン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的2只风属性怪兽回到卡组，选择场上存在的1张卡回到持有者手卡。'),
(23571046, 'Quillbolt Hedgehog', '螺丝刺猬', 'ボルト・ヘッジホッグ', 'Effect Monster', 'Machine', 'EARTH', 2, 800, 800, '①：自己主要阶段才能发动。这张卡从墓地特殊召唤。这个效果在自己场上有调整存在的场合才能发动和处理。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(84433295, 'Quintet Magician', '五重魔导师', 'クインテット・マジシャン', 'Fusion Monster', 'Spellcaster', 'DARK', 12, 4500, 4500, '魔法师族怪兽×5 这张卡不用融合召唤不能特殊召唤。 ①：魔法师族怪兽5种类作为素材让这张卡融合召唤的场合才能发动。对方场上的卡全部破坏。 ②：这张卡只要在怪兽区域存在，不能解放，不能作为融合素材，不会被效果破坏。');